--- 刷新页面
function SettingPushPanel:RefreshPanel()
    if isNotNull(self.btnObjList) then
        -- 已经初始化过了，只刷新多语言文字
        self:RefreshText()
        return
    end
    -- 初始化按钮
    self.btnObjList = {}
    self.oldBtnStateList = self:LoadBtnStateList()
    local isZM = SDKService:IsZm()
    local isClosePush = 0
    if isZM then
        local PlayerPrefsUtility = CS.Engine.Tools.PlayerPrefsUtility
        local isOpen = PlayerPrefsUtility.GetEncryptedString("isOpenNotice" , "0")
        isClosePush = checkInt(isOpen) == 1 and 0 or 1  
    end
    for i, sectionData in ipairs(PanelData) do
        local root = self:GetSectionRoot(i)

        for j, btnData in ipairs(sectionData) do
            local btn = KTool.Instantiate(root.gameObject, self.RT_SwitchBtn.gameObject)
            KTool.SetActive(btn, true)
            -- 按钮文本
            self:SetBtnText(btn, btnData)
            -- 设置按钮状态
            local state = self:GetOldBtnState(btnData.id)
            if isClosePush == 1 then
                state = 0 
            end
            local btnLB = GetLuaBehaviour(btn.transform:Find("SettingSwitchNode").gameObject, "Game.UI.Setting.SettingSwitchNode")
            btnLB.Env:FreshSwitchStatus(state == 0)
            btnLB.Env:SetCallBack(function()
                btnLB.Env:Switch()
                if btnData.id == "main" then
                    if btnLB.Env.openState then
                        SDKService:firebaseOpen()
                    else 
                        SDKService:firebaseClose()
                    end
                end
            end)
            table.insert(self.btnObjList, {data = btnData, go = btn, lb = btnLB})
        end
    end
end

function SettingPushPanel:SetBtnText(btn, btnData)
    local btnName = btnData.name()
    local btnText = btn.transform:Find("Text"):GetComponent(typeof(Text))
    btnText.text = btnName
    local btnDesc = btnData.desc and btnData.desc() or nil
    if isNotNull(btnDesc) then
        local btnText2 = btn.transform:Find("Text/Text2"):GetComponent(typeof(Text))
        btnText2.text = btnDesc
        KTool.SetActive(btnText2.gameObject, true)
    end
end

--- 刷新本地化文本
function SettingPushPanel:RefreshText()
    for i, v in ipairs(self.btnObjList) do
        local btnData = v.data
        local btn = v.go
        self:SetBtnText(btn, btnData)
    end
end

function SettingPushPanel:LoadBtnStateList()
    -- 读取保存的状态
    local btnStateList = {}
    local json = GameUtils.LoadString(BtnStateListKey, "")
    -- print("[推送] 读取按钮状态", json)
    if not string.isEmpty(json) then
        btnStateList = table.deserialize(json)
    end

    -- 如果有服务器未及时添加的按钮，补充默认值为1
    for i, sectionData in ipairs(PanelData) do
        for j, btnData in ipairs(sectionData) do
            if isNull(btnStateList[btnData.id]) then
                btnStateList[btnData.id] = 1
            end
        end
    end
    
    return btnStateList
end

--- 保存按钮状态
function SettingPushPanel:SaveBtnStateList()
    local hasChange, newBtnStateList = self:HasChange()
    if hasChange then
        local json = table.serialize(newBtnStateList)
        -- print("[推送] 保存按钮状态", json)
        -- 保存到本地
        GameUtils.SaveString(BtnStateListKey, json)
    end
end

function SettingPushPanel:HasChange()
    -- 旧状态
    local oldBtnStateList = {}
    local json = GameUtils.LoadString(BtnStateListKey)
    if not string.isEmpty(json) then
        oldBtnStateList = table.deserialize(json)
    end
    -- 新状态
    local newBtnStateList = {}
    for i, v in ipairs(self.btnObjList) do
        local id = v.data.id
        local state = v.lb.Env.openState and 1 or 0
        newBtnStateList[id] = state
    end
    -- 比较状态
    local changed = false
    for id, state in pairs(newBtnStateList) do
        if isNull(oldBtnStateList[id]) then
            changed = true
            break
        end
        if oldBtnStateList[id] ~= state then
            changed = true
            break
        end
    end
    return changed, newBtnStateList
end

--- 推送总开关是否有变化
function SettingPushPanel:IsMainBtnStateChanged()
    -- 旧状态
    local oldBtnStateList = {}
    local json = GameUtils.LoadString(BtnStateListKey)
    if not string.isEmpty(json) then
        oldBtnStateList = table.deserialize(json)
    end
    -- 新状态
    local newBtnStateList = {}
    for i, v in ipairs(checkTable(self.btnObjList)) do
        local id = v.data.id
        local state = v.lb.Env.openState and 1 or 0
        newBtnStateList[id] = state
    end

    local mainId = "main"
    local mainBtnChanged = newBtnStateList[mainId] ~= oldBtnStateList[mainId]
    return mainBtnChanged, newBtnStateList[mainId]
end

--- SettingDialog会调用这个接口获取json，发送给服务器
function SettingPushPanel:GetPushBtnsChangedState()
    if isNull(self.btnObjList) then
        -- 没开过这个页面，直接返回旧状态
        return false, GameUtils.LoadString(BtnStateListKey)
    else
        -- 打开过页面
        local changed, newBtnStateList = self:HasChange()

        return changed, table.serialize(newBtnStateList)
    end
end

return SettingPushPanel